import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outfile = path.join(root, 'ops', 'laprakin-email-renderer.mjs');

await build({
  entryPoints: [path.join(root, 'ops', 'laprakin-email-renderer-entry.mjs')],
  outfile,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  minify: true,
  legalComments: 'none',
  banner: {
    js: [
      '// Generated by npm run email:ops:build. Do not edit directly.',
      "import { createRequire as __createRequire } from 'node:module';",
      'const require = __createRequire(import.meta.url);',
    ].join('\n'),
  },
});

const bundle = await fs.readFile(outfile, 'utf8');
await fs.writeFile(outfile, bundle.replace(/[ \t]+$/gm, ''), 'utf8');
